import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Fused HardSwish + ReLU kernel
hardswish_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_hardswish_relu_kernel(const float* input, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float x = input[idx];
        float hs = x * fminf(fmaxf(x + 3.0f, 0.0f), 6.0f) / 6.0f;
        output[idx] = fmaxf(hs, 0.0f);
    }
}

torch::Tensor fused_hardswish_relu_cuda(torch::Tensor input) {
    auto output = torch::zeros_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    const int num_blocks = (num_elements + block_size - 1) / block_size;
    fused_hardswish_relu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), num_elements);
    return output;
}
"""

hardswish_relu_cpp = "torch::Tensor fused_hardswish_relu_cuda(torch::Tensor input);"

fused_hardswish_relu = load_inline(
    name='fused_hardswish_relu',
    cpp_sources=hardswish_relu_cpp,
    cuda_sources=hardswish_relu_source,
    functions=['fused_hardswish_relu_cuda'],
    verbose=True
)

# Fused Softmax + Mean kernel
softmax_mean_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void softmax_mean_kernel(const float* input, float* output, int B, int C, int N) {
    int batch_idx = blockIdx.x / N;
    int spatial_idx = blockIdx.x % N;

    extern __shared__ float shared_data[];
    int tid = threadIdx.x;

    if (tid < C) {
        int input_idx = batch_idx * C * N + tid * N + spatial_idx;
        shared_data[tid] = input[input_idx];
    } else {
        shared_data[tid] = -FLT_MAX;
    }
    __syncthreads();

    float max_val = -FLT_MAX;
    for (int i = 0; i < C; ++i) {
        if (shared_data[i] > max_val) max_val = shared_data[i];
    }

    float sum_exp = 0.0f;
    for (int i = 0; i < C; ++i) {
        sum_exp += expf(shared_data[i] - max_val);
    }

    if (tid < C) {
        float softmax_val = expf(shared_data[tid] - max_val) / sum_exp;
        float contribution = softmax_val / N;
        atomicAdd(&output[batch_idx * C + tid], contribution);
    }
}

torch::Tensor softmax_mean_cuda(torch::Tensor input) {
    int B = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);
    int N = D * H * W;

    auto output = torch::zeros({B, C}, input.options());

    dim3 grid(B * N);
    dim3 block(C);
    size_t shared_mem_size = C * sizeof(float);

    softmax_mean_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        B, C, N
    );

    return output;
}
"""

softmax_mean_cpp = "torch::Tensor softmax_mean_cuda(torch::Tensor input);"

fused_softmax_mean = load_inline(
    name='fused_softmax_mean',
    cpp_sources=softmax_mean_cpp,
    cuda_sources=softmax_mean_source,
    functions=['softmax_mean_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, bias=True):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size, bias=bias)
        self.fused_hardswish_relu = fused_hardswish_relu
        self.fused_softmax_mean = fused_softmax_mean

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_hardswish_relu.fused_hardswish_relu_cuda(x)
        x = self.fused_softmax_mean.softmax_mean_cuda(x)
        return x
